  eta(1).^(3.*gamma2)+((-18)+11.*gamma2+6.*gamma2.^2+gamma2.^3).* ...
  eta(1).^(2.*gamma2).*eta(2).^gamma2+(-2).*(9+(-11).*gamma2+2.* ...
  gamma2.^3).*eta(1).^gamma2.*eta(2).^(2.*gamma2)+((-6)+11.*gamma2+( ...
